import { test, expect, type Page } from "@playwright/test";
import { readFileSync, promises as fs } from "node:fs";
import path from "node:path";

// This workbook was generated by the real API tests in disposable PostgreSQL.
// All records say NAMUNA. It is outside public/ and never serves as business data.
const fixture = readFileSync(
  path.join(process.cwd(), "tests/fixtures/excel-report.xlsx"),
);

async function mount(page: Page) {
  const state = {
    mode: "ok",
    urls: [] as string[],
    release: undefined as (() => void) | undefined,
  };
  await page.route("**/api/v1/**", async (route) => {
    const url = new URL(route.request().url());
    if (url.pathname.endsWith("/auth/me"))
      return route.fulfill({
        json: {
          id: "fixture",
          role: "teacher",
          username: "NAMUNA ustoz",
          must_change_password: false,
        },
      });
    if (url.pathname.endsWith("/reports/summary"))
      return route.fulfill({
        json: {
          student_count: 2,
          group_count: 1,
          received: "400000.01",
          overdue: "200000.00",
        },
      });
    if (url.pathname.endsWith("/reports/export.xlsx")) {
      state.urls.push(url.search);
      if (state.mode === "hold")
        await new Promise<void>((resolve) => {
          state.release = resolve;
        });
      if (state.mode === "error")
        return route.fulfill({ status: 403, json: { message: "Ruxsat yo‘q" } });
      if (state.mode === "html")
        return route.fulfill({
          contentType: "text/html",
          body: "<p>Error</p>",
        });
      return route.fulfill({
        contentType:
          "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        body: fixture,
      });
    }
    return route.fulfill({ json: { items: [], total: 0 } });
  });
  return state;
}

test("reports download an Excel workbook for the selected month", async ({
  page,
}, info) => {
  const state = await mount(page);
  await page.goto("/teacher/reports");
  await page.getByLabel("Hisobot oyi", { exact: true }).fill("2026-10");
  const pending = page.waitForEvent("download");
  await page
    .getByRole("button", { name: "Barcha hisobotlar (Excel)", exact: true })
    .click();
  const download = await pending;
  expect(download.suggestedFilename()).toBe("sherzod-all-2026-10.xlsx");
  expect(state.urls.at(-1)).toContain("month=2026-10-01");
  await download.saveAs(info.outputPath("report.xlsx"));
  expect(await fs.readFile(info.outputPath("report.xlsx"))).toEqual(fixture);
  await expect(
    page
      .getByTestId("notification")
      .filter({ hasText: "Excel fayli yuklab olishga tayyorlandi." }),
  ).toBeVisible();
  await expect(page).toHaveURL(/\/teacher\/reports$/);
});

test("Excel buttons work on finance and student/group lists on a phone", async ({
  page,
}) => {
  const state = await mount(page);
  await page.setViewportSize({ width: 375, height: 812 });
  for (const [url, button, resource] of [
    ["finance", "Barcha moliya (Excel)", "finance"],
    ["students", "Barcha yozuvlar (Excel)", "students"],
    ["groups", "Barcha yozuvlar (Excel)", "groups"],
  ]) {
    await page.goto(`/teacher/${url}`);
    const pending = page.waitForEvent("download");
    await page.getByRole("button", { name: button, exact: true }).click();
    const download = await pending;
    expect(download.suggestedFilename()).toBe(`sherzod-${resource}.xlsx`);
    expect(state.urls.at(-1)).toContain(`resource=${resource}`);
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth + 1,
      ),
    ).toBe(true);
  }
  await page.goto("/teacher/reports");
  await page.screenshot({
    path: "../docs/qa/excel-reports-375.png",
    fullPage: true,
  });
});

test("failed Excel preparation can be retried and disables duplicate downloads", async ({
  page,
}) => {
  const state = await mount(page);
  const downloads: string[] = [];
  page.on("download", (download) =>
    downloads.push(download.suggestedFilename()),
  );
  await page.goto("/teacher/reports");
  const button = page.getByRole("button", {
    name: "O‘quvchilar (Excel)",
    exact: true,
  });
  for (const mode of ["error", "html"]) {
    state.mode = mode;
    await button.click();
    await expect(
      page
        .getByTestId("notification")
        .filter({ hasText: "Excel fayli yuklanmadi." }).last(),
    ).toBeVisible();
    await expect(button).toBeEnabled();
  }
  expect(downloads).toEqual([]);
  state.mode = "hold";
  await button.click();
  await expect(
    page.getByRole("button", { name: "Tayyorlanmoqda…", exact: true }),
  ).toBeDisabled();
  await expect.poll(() => Boolean(state.release)).toBe(true);
  state.release!();
  await expect.poll(() => downloads.length).toBe(1);
  await expect(button).toBeEnabled();
});
